import React, { useRef } from 'react';

const MediaUploader = ({ type, multiple, onUpload, uploadedFiles, setUploadedFiles }) => {
    const fileInputRef = useRef(null);

    const handleClick = () => {
        fileInputRef.current.click();
    };

    const handleFileChange = (e) => {
        if (e.target.files && e.target.files.length > 0) {
            onUpload(e.target.files);
        }
    };

    const handleDragOver = (e) => {
        e.preventDefault();
        e.stopPropagation();
    };

    const handleDrop = (e) => {
        e.preventDefault();
        e.stopPropagation();

        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            const validFiles = Array.from(e.dataTransfer.files).filter(file => {
                if (type === 'image') {
                    return file.type.startsWith('image/');
                } else if (type === 'video') {
                    return file.type.startsWith('video/');
                }
                return false;
            });

            if (validFiles.length > 0) {
                onUpload(validFiles);
            }
        }
    };

    const removeFile = (index) => {
        const newFiles = [...uploadedFiles];
        newFiles.splice(index, 1);
        setUploadedFiles(newFiles);
    };

    const getAcceptAttribute = () => {
        if (type === 'image') return 'image/*';
        if (type === 'video') return 'video/*';
        return '';
    };

    return (
        <div className="space-y-4">
            <div
                className={`border-2 border-dashed rounded-lg p-4 text-center cursor-pointer hover:bg-gray-50 transition-colors ${uploadedFiles.length > 0 ? 'border-green-300' : 'border-gray-300'
                    }`}
                onClick={handleClick}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
            >
                <input
                    type="file"
                    ref={fileInputRef}
                    className="hidden"
                    onChange={handleFileChange}
                    accept={getAcceptAttribute()}
                    multiple={multiple}
                />

                <div className="py-4">
                    <svg
                        xmlns="http://www.w3.org/2000/svg"
                        className="h-12 w-12 mx-auto text-gray-400"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                    >
                        {type === 'image' ? (
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={1}
                                d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                            />
                        ) : (
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={1}
                                d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"
                            />
                        )}
                    </svg>

                    <p className="mt-2 text-sm text-gray-500">
                        {uploadedFiles.length === 0 ? (
                            <>
                                <span className="font-medium text-gray-900">Click to upload</span> or drag and drop
                                <br />
                                {type === 'image' && multiple && 'Upload multiple images'}
                                {type === 'image' && !multiple && 'Upload an image'}
                                {type === 'video' && 'Upload a video'}
                            </>
                        ) : (
                            <>
                                <span className="font-medium text-green-600">
                                    {uploadedFiles.length} {type === 'image' ? 'image' : 'video'}
                                    {uploadedFiles.length > 1 ? 's' : ''} uploaded
                                </span>
                                <br />
                                Click to add more or replace
                            </>
                        )}
                    </p>
                </div>
            </div>

            {/* Preview section */}
            {uploadedFiles.length > 0 && (
                <div className={`grid grid-cols-${multiple ? '2' : '1'} gap-2`}>
                    {uploadedFiles.map((file, index) => (
                        <div key={index} className="relative group">
                            {type === 'image' ? (
                                <img
                                    src={file.preview}
                                    alt={`Preview ${index + 1}`}
                                    className="w-full h-24 object-cover rounded-lg"
                                />
                            ) : (
                                <video
                                    src={file.preview}
                                    className="w-full h-24 object-cover rounded-lg"
                                    controls
                                />
                            )}
                            <button
                                type="button"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    removeFile(index);
                                }}
                                className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                                </svg>
                            </button>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default MediaUploader;
